#include <iostream>
#include <string>
#include <vector>
#include <functional>
#include <sstream>

// ---------------- 极简单元测试框架（本章自研） ----------------
// 目标：不依赖 googletest，用 60 行说明「测试框架到底做了什么」：
// ① 用例注册（宏 + 全局注册表）② 断言计数 ③ 失败定位 ④ 汇总与退出码语义
namespace mini {

struct Stats { int tests = 0, failed_tests = 0, checks = 0, failed_checks = 0; };

class Registry {
public:
    static Registry& instance() { static Registry r; return r; }

    void add(const std::string& name, std::function<void()> fn) {
        cases_.push_back(Case{name, std::move(fn)});
    }

    int run() {
        for (auto& c : cases_) {
            std::cout << "[ RUN  ] " << c.name << "\n";
            int before = st_.failed_checks;
            c.fn();
            ++st_.tests;
            if (st_.failed_checks > before) {
                ++st_.failed_tests;
                std::cout << "[ FAIL ] " << c.name << "\n";
            } else {
                std::cout << "[  OK  ] " << c.name << "\n";
            }
        }
        std::cout << "[SUMMARY] 用例=" << st_.tests << " 失败用例=" << st_.failed_tests
                  << " 断言=" << st_.checks << " 失败断言=" << st_.failed_checks << "\n";
        std::cout << "[CI] 退出码语义=" << (st_.failed_checks ? 1 : 0) << "\n";
        return st_.failed_checks ? 1 : 0;
    }

    void check(bool ok, int line, const std::string& msg) {
        ++st_.checks;
        if (!ok) {
            ++st_.failed_checks;
            std::cout << "[ ASSERT ] 第" << line << "行: " << msg << "\n";
        }
    }

    template <typename A, typename B>
    void eq(const A& a, const B& b, int line, const char* ea, const char* eb) {
        std::ostringstream os;
        if (!(a == b)) os << ea << " == " << eb << " 期望=" << b << " 实得=" << a;
        check(a == b, line, os.str());
    }

private:
    struct Case { std::string name; std::function<void()> fn; };
    std::vector<Case> cases_;
    Stats st_;
};

struct Registrar {
    Registrar(const char* n, std::function<void()> fn) {
        Registry::instance().add(n, std::move(fn));
    }
};

}  // namespace mini

#define TEST(name)                                            \
    static void name();                                       \
    static mini::Registrar mini_reg_##name(#name, name);       \
    static void name()

#define CHECK_EQ(a, b) mini::Registry::instance().eq((a), (b), __LINE__, #a, #b)
#define CHECK_TRUE(x)  mini::Registry::instance().check(static_cast<bool>(x), __LINE__, #x)
#define MINI_MAIN()    int main() { return mini::Registry::instance().run(); }

#include <chrono>

// ---------------- 抽象接口：唯一被测试代码"认识"的契约 ----------------
struct IClock {
    virtual ~IClock() = default;
    virtual long long now_ms() const = 0;
};

struct FakeClock : IClock {                  // 假实现：时间完全由测试驱动
    long long t = 0;
    long long now_ms() const override { return t; }
    void advance(long long d) { t += d; }
};

struct SystemClock : IClock {                // 真实现：生产环境注入
    long long now_ms() const override {
        using namespace std::chrono;
        return duration_cast<milliseconds>(steady_clock::now().time_since_epoch()).count();
    }
};

// 依赖注入：RateLimiter 只持有 IClock 引用，从不自己取系统时间
class RateLimiter {
public:
    RateLimiter(const IClock& clk, int capacity, long long window_ms)
        : clk_(clk), cap_(capacity), win_(window_ms) {}

    bool allow() {
        long long now = clk_.now_ms();
        if (start_ < 0 || now - start_ >= win_) { start_ = now; used_ = 0; }
        if (used_ < cap_) { ++used_; return true; }
        return false;
    }

private:
    const IClock& clk_;
    int cap_;
    long long win_;
    long long start_ = -1;
    int used_ = 0;
};

static const char* B(bool v) { return v ? "True" : "False"; }

int main() {
    std::cout << "[DI] 注入 FakeClock：被测逻辑零改动，无需 mock 框架\n";
    FakeClock fake;
    RateLimiter rl(fake, 3, 1000);
    for (int i = 1; i <= 5; ++i)
        std::cout << "t=" << fake.now_ms() << " 第" << i << "次 allow=" << B(rl.allow()) << "\n";
    fake.advance(1000);
    std::cout << "t=" << fake.now_ms() << " 第6次 allow=" << B(rl.allow()) << "\n";

    SystemClock real_clk;
    long long a = real_clk.now_ms();
    long long b = real_clk.now_ms();
    std::cout << "[BOOLEAN] SystemClock 单调不减=" << B(b >= a) << "\n";
    std::cout << "[NOTE] 生产环境把 SystemClock 传进去即可，RateLimiter 是可测的\n";
    return mini::Registry::instance().run();
}
